@page "/chat"
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout @(threadOpen ? "thread-open" : "")">
    <ChannelSidebar Channels="channels"
                    SelectedChannelId="selectedChannelId"
                    OnChannelSelected="SelectChannel" />

    <MessageArea ChannelName="@currentChannelName"
                 ChannelDescription="@currentChannelDescription"
                 Messages="messages"
                 ThreadSummaries="threadSummaries"
                 IsLoadingMore="isLoadingMore"
                 OnOpenThread="OpenThread"
                 OnReact="HandleReaction"
                 OnLoadMore="LoadMoreMessages"
                 OnSendMessage="SendMessage" />

    @if (threadOpen)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     ThreadMessages="threadMessages"
                     OnClose="CloseThread"
                     OnReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = new();
    private List<Message> messages = new();
    private List<ThreadSummary> threadSummaries = new();
    private List<Message> threadMessages = new();
    private Message? threadRootMessage;

    private int selectedChannelId;
    private string currentChannelName = string.Empty;
    private string currentChannelDescription = string.Empty;
    private bool threadOpen;
    private bool isLoadingMore;
    private int messageSkip;
    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannelId = channelId;
        var channel = channels.First(c => c.Id == channelId);
        currentChannelName = channel.Name;
        currentChannelDescription = channel.Description;

        messageSkip = 0;
        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        messageSkip = messages.Count;
        threadSummaries = BuildThreadSummaries(messages);

        await ChatService.MarkChannelReadAsync(channelId);

        // Update local unread count
        var idx = channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            channels[idx] = channel with { UnreadCount = 0 };
        }

        CloseThread();
    }

    private async Task LoadMoreMessages()
    {
        if (isLoadingMore) return;
        isLoadingMore = true;

        var older = await ChatService.GetMessagesAsync(selectedChannelId, messageSkip, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            messageSkip += older.Count;
            threadSummaries = BuildThreadSummaries(messages);
        }

        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        var sent = await ChatService.SendMessageAsync(selectedChannelId, content, null);
        messages.Add(sent);
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        threadMessages = await ChatService.GetThreadAsync(messageId);
        threadOpen = true;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadMessages = new();
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannelId, content, threadRootMessage.Id);
        threadMessages.Add(reply);
        threadSummaries = BuildThreadSummaries(messages, threadRootMessage.Id, threadMessages.Count);
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to show updated reactions
        messages = await ChatService.GetMessagesAsync(selectedChannelId, 0, messageSkip > 0 ? messageSkip : PageSize);
    }

    private List<ThreadSummary> BuildThreadSummaries(List<Message> msgs, int? updatedThreadId = null, int? updatedCount = null)
    {
        var replies = msgs.Where(m => m.ReplyToId.HasValue)
            .GroupBy(m => m.ReplyToId!.Value)
            .Select(g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
            .ToList();

        if (updatedThreadId.HasValue && updatedCount.HasValue)
        {
            var existing = replies.FindIndex(t => t.RootMessageId == updatedThreadId.Value);
            if (existing >= 0)
            {
                replies[existing] = replies[existing] with { ReplyCount = updatedCount.Value };
            }
            else
            {
                replies.Add(new ThreadSummary(updatedThreadId.Value, updatedCount.Value, DateTime.Now));
            }
        }

        return replies;
    }
}

