toolArgs.file_text:
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* Channel Sidebar */
::deep .channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #1a1d21;
    color: #ccc;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #333;
    overflow-y: auto;
}

::deep .sidebar-title {
    padding: 16px 16px 8px;
    font-size: 1rem;
    color: #fff;
    margin: 0;
}

::deep .channel-list {
    flex: 1;
    overflow-y: auto;
}

::deep .channel-item {
    padding: 8px 16px;
    cursor: pointer;
    border-left: 3px solid transparent;
    position: relative;
}

::deep .channel-item:hover {
    background: #26292e;
}

::deep .channel-item.active {
    background: #1264a3;
    border-left-color: #fff;
    color: #fff;
}

::deep .channel-name {
    font-weight: 600;
    font-size: 0.9rem;
}

::deep .channel-description {
    font-size: 0.75rem;
    color: #999;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

::deep .channel-item.active .channel-description {
    color: #ddd;
}

::deep .unread-badge {
    position: absolute;
    top: 8px;
    right: 12px;
    background: #e01e5a;
    color: #fff;
    border-radius: 10px;
    padding: 2px 7px;
    font-size: 0.7rem;
    font-weight: 700;
}

/* Message Area */
::deep .message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #fff;
    min-width: 0;
}

::deep .channel-header {
    padding: 12px 20px;
    border-bottom: 1px solid #e0e0e0;
}

::deep .channel-header h2 {
    margin: 0;
    font-size: 1.1rem;
}

::deep .channel-header .channel-desc {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #666;
}

::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 12px 20px;
}

::deep .loading-indicator {
    text-align: center;
    padding: 8px;
